/** A folder the person keeps projects in. */
export interface ProjectRoot {
    path: string;
    /** How many folders below it git repositories count as projects. */
    depth: number;
    /** The folder is a project itself, whether or not it is a git repository. */
    selfIndex?: boolean;
}

/** A shell command the person added to the command palette. */
export interface CustomCommand {
    id: string;
    title: string;
    detail?: string;
    command: string;
    /** The kinds of tab it is offered in; none means every tab. */
    contexts?: string[];
    placement: CustomCommandPlacement;
}

export type CustomCommandPlacement = "background" | "terminal" | "split" | "popup" | "replace";

/** The Notch section of the person's preferences, which the island reads. */
export interface NotchSettings {
    enabled: boolean;
    displays: NotchDisplays;
    openWith: NotchOpenWith;
    fullScreen: NotchFullScreen;
    peeks: NotchPeeks;
    answerInNotch: boolean;
    sound: boolean;
    haptics: boolean;
    /** Only a stable or nightly build reads this: whether it steps aside while Sikemux Dev runs. */
    yieldToDev: boolean;
}

export type NotchDisplays = "all" | "builtIn" | "pointer";

export type NotchOpenWith = "hover" | "click";

export type NotchFullScreen = "needsYou" | "always" | "never";

export type NotchPeeks = "all" | "needsYou" | "never";

/**
 * Where the pane picture's inks come from: the theme's ground, accent and ink, the picture's
 * own colours, or the person's three.
 */
export type PaneColours = "theme" | "picture" | "custom";

/** The grid that decides which of two inks each dot takes, or random noise. */
export type PanePattern = "bayer2" | "bayer4" | "bayer8" | "noise";

/** How much of a pane the picture covers: a band at its top fading down, or all of it. */
export type PaneCoverage = "band" | "full";

export type RailDensity = "comfortable" | "compact";

export type TabRailPage = "agents" | "terminals" | "files";

/** Whose agents the tab rail lists: the project in front's, or every project's. */
export type TabRailScope = "project" | "all";

/** What the window shows in place of the other. */
export type WindowView = "workbench" | "goals";

/** The picked theme with the colours every app draws with, worked out from it. */
export interface Palette {
    theme: Theme;
    tokens: UiTokens;
}

/**
 * DESIGN.md's colours for one theme, each `#rrggbb`, or `rgba(r, g, b, a)`
 * when see-through. Phones read them by these names from the device view.
 */
